{"path": "creative_intent.json", "content": "{
  "user_need": "1992年，男主是倒爷（个体户），骑嘉陵摩托穿州过省做生意，女主是国营厂下岗女工。他让她坐在后座押货，从南方到北方，七天七夜。她以为是雇佣关系，其实他在进行一场"流浪婚礼"——每经过一个县城就供销社买一对枕巾（内部鸳鸯图案），堆满了摩托车的边斗。最后一天他告诉她"如果这单赚了，我娶你；如果赔了，摩托归你，我归摩托（死在路上）"。结果是赔了，但她把摩托卖了，买了两张去深圳的车票。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["获取", "漂泊", "定情", "牺牲"],
    "scene_elements": ["1992年", "嘉陵摩托车", "倒爷经济", "下岗女工", "供销社", "深圳"],
    "relationship_tension": ["雇佣关系vs暗恋", "个体户vs下岗女工身份差异", "经济风险下的爱情赌注"],
    "user_preferences": {
      "desired_emotion": "时代洪流下身不由己的虐感，但最终走向新生",
      "forbidden": ["超自然元素", "系统/重生/穿越", "第三者插足", "狗血桥段"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "E28",
    "x_axis_mode_name": "爱情的阻碍",
    "y_axis_tags": ["双向暗恋", "商战权谋"],
    "reaction_strength": "↘",
    "tension_stars": 3,
    "forbidden_elements": ["不要超自然元素", "不要系统/重生/穿越", "不要第三者插足", "不要突然失忆/绝症", "不要强行HE"],
    "x_axis_display": "身份差异（个体户vs下岗女工）、经济风险（可能赔本死在路上）、社会偏见（倒爷不稳定vs国营厂铁饭碗破碎），两人在七天七夜中跨越这些阻碍。",
    "y_axis_combination_effect": "商战权谋为'爱情阻碍'增加道德困境——他可能赔了，她是否还跟他走？双向暗恋加剧痛苦——她以为只是雇佣，他赌上全部身家，信息差制造虐恋张力。",
    "reaction_formula": "时代的洪流 + 隐秘的爱意 = 赌上一切的流浪婚礼",
    "platform_fit": ["豆瓣阅读", "知乎盐选", "晋江"]
  },
  "one_sentence_synopsis": "1992年，倒爷载着下岗女工骑摩托七天七夜北上，她用枕巾堆成婚床，他赌上全部身家。"
}"}

{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈劲",
      "role": "protagonist",
      "identity": "个体户/倒爷",
      "traits": ["胆大心细", "浪漫隐忍", "赌徒心态", "重情义"],
      "overt_motivation": "把这单生意做成，赚够钱娶她",
      "covert_motivation": "给她一个家，证明自己不是'不务正业'的倒爷",
      "secret_fear": "赔了，没资格娶她，只能死在路上",
      "misperception_of_other": "以为她只看钱，其实她早就动心",
      "hidden_connection": "策划了一场'流浪婚礼'，每经过一个县城买一对鸳鸯枕巾当聘礼"
    },
    {
      "name": "苏晓",
      "role": "deuteragonist",
      "identity": "国营厂下岗女工",
      "traits": ["坚韧务实", "外冷内热", "自尊心强", "细腻敏感"],
      "overt_motivation": "押货赚钱，攒钱去深圳",
      "covert_motivation": "寻找归属感，被需要被珍视",
      "secret_fear": "再次被抛弃，成为累赘",
      "misperception_of_other": "以为他只是雇她押货，不知道这是他的'流浪婚礼'",
      "hidden_connection": "偷偷在地图上画心，早就动心却不敢说破"
    }
  ],
  "supporting_characters": [
    {
      "name": "供销社老板娘",
      "function": "助力",
      "identity": "县城供销社售货员",
      "description": "卖枕巾给他们，说些意味深长的话，暗示枕巾的寓意"
    },
    {
      "name": "检查站人员",
      "function": "阻碍",
      "identity": "路政检查员",
      "description": "路上查车，制造紧张感，考验两人的信任"
    }
  ],
  "relationship_dynamics": "从雇佣关系开始，七天七夜的封闭空间（摩托车）中逐渐产生情愫。他是策划者（暗恋），她是被动接受者（逐渐动心）。信息差制造张力：读者知道他的真实意图，她不知道，直到最后才揭晓。结局她卖摩托买两张车票，是对他赌注的回应——她选择跟他一起走，不管去哪。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立世界观（1992年倒爷经济）、引入主角和核心冲突（雇佣关系下的暗恋）、建立七天七夜的倒计时紧迫感",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "嘉陵发动",
        "core_event": "陈劲载着苏晓从南方出发，告诉她这单七天，到了北方结钱。苏晓坐上后座，边斗里装着样品。",
        "emotional_tone": "克制、疏离",
        "key_scenes": ["摩托车发动的轰鸣声", "苏晓犹豫后坐上后座", "陈劲说'抓紧了'", "第一天的路程开始"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第一个县城",
        "core_event": "经过第一个县城，陈劲拐进供销社买枕巾，说是样品。苏晓以为是生意需要，没多想。",
        "emotional_tone": "疑惑、试探",
        "key_scenes": ["供销社里鸳鸯枕巾的特写", "老板娘意味深长的话", "枕巾放进边斗", "第一夜路边过夜，陈劲把枕巾铺地上让她睡"]
      }
    ],
    "turning_point": "第一夜，陈劲把新买的枕巾铺在地上让苏晓睡，自己睡旁边。苏晓第一次觉得这个人不一样。"
  },
  "act_two": {
    "description": "冲突螺旋升级（外部：暴雨/检查站/生意风险；内部：苏晓逐渐发现枕巾的异常、陈劲的隐忍）、情感递进（雇佣→共谋→暗恋浮现）",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "暴雨与红丝巾",
        "core_event": "第二天遭遇暴雨，陈劲停车冒雨买红丝巾给她。苏晓在地图上偷偷画心。",
        "emotional_tone": "悸动、隐秘",
        "key_scenes": ["暴雨中摩托车艰难前行", "陈劲停车冲进雨里", "红丝巾系在她脖子上", "苏晓在地图上画心"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "边斗满了",
        "core_event": "第三到第五天，经过多个县城，枕巾越堆越多。苏晓开始怀疑，发现都是鸳鸯图案。",
        "emotional_tone": "怀疑、不安",
        "key_scenes": ["检查站查车，枕巾差点暴露", "苏晓数枕巾，发现都是成对的", "她问'买这么多干嘛'", "陈劲回避问题"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "一万张婚床",
        "core_event": "第六夜桥洞下过夜，陈劲把所有枕巾铺开当床，说'现在我们有一万张婚床'。苏晓震惊。",
        "emotional_tone": "震撼、情感觉醒",
        "key_scenes": ["桥洞下避雨", "枕巾铺满地面", "陈劲说'一万张婚床'", "苏晓第一次正视他的眼睛", "两人几乎捅破窗户纸"]
      }
    ],
    "turning_point": "第六夜，陈劲说出'一万张婚床'，苏晓意识到这不是普通的生意旅程。她开始明白他的心意，但也明白他可能在赌命。"
  },
  "act_three": {
    "description": "高潮（第七天到达目的地，生意赔了）+ 结局（陈劲说出赌注，苏晓卖摩托买两张车票）",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "两张车票",
        "core_event": "第七天到达北方，生意赔了。陈劲说'如果赔了，摩托归你，我归摩托'。苏晓把摩托卖了，买了两张去深圳的车票。",
        "emotional_tone": "释然、新生",
        "key_scenes": ["到达目的地，对方毁约", "陈劲说出赌注", "苏晓沉默后卖摩托", "售票窗口买两张车票", "结尾：两人站在车站，车票在手"]
      }
    ],
    "turning_point": "苏晓卖摩托买两张车票——她不接受他的'牺牲'，她选择跟他一起走，不管去哪。这是对'流浪婚礼'的回应。"
  }
}"}

